// This node sits ONLY on the public webhook branch.
//
// Until now `POST /webhook/nexus-inbound-lead` was wide open. Anyone who found
// the URL could invent a lead, have an LLM score it, get a row written into
// `leads`, and -- on a HOT verdict -- make the dealership send a WhatsApp
// message to any number they chose. Every other public webhook in this system
// already checks the caller's Supabase session token; this one never did,
// because its only intended caller was Make.com, which no longer exists.
//
// `Called Internally` (the Execute Workflow trigger) connects straight to
// `Validate & Enrich Input` and never reaches here, so n8n-to-n8n calls are
// untouched -- they are already inside the trust boundary.
//
// `Verify JWT` runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
const auth = $input.first().json || {};
if (!auth.id) {
  throw new Error('Inbound lead rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so `Validate & Enrich Input` sees
// exactly the shape it saw before this guard was inserted.
return $('Webhook Catch-All').all();

// Delivery Report - verify every claim the audit row is about to make.
//
// Only ONE intent branch runs per lead, and `$('Node')` THROWS for a node that
// did not run -- `?.` cannot rescue it -- so the claim list is built from the
// intent that actually fired, and every lookup is still wrapped.
const decision = $('Parse AI Decision').first().json;
const intent = String((decision.ai_decision || {}).intent || 'UNKNOWN').toUpperCase();
const origin = String(((decision.lead) || {}).origin || 'external');

const CLAIMED = [];

// 29 Aug 2026: the lead write is claimed on EVERY branch, unconditionally, and
// it is pushed FIRST so CLAIMED can never be empty.
// Before this, a WARM lead with origin 'whatsapp-bdc' pushed nothing at all --
// the WARM arm has no else -- so results.length was 0 and the report said
// 'all 0 claimed steps verified' with status SUCCESS. Execution 6253 did exactly
// that on a run which created no leads row whatsoever. The report only ever
// verified dispatch; it never verified persistence, which is the one thing every
// downstream journey depends on.
CLAIMED.push({ node: 'Persist Lead (deterministic)', what: 'lead row written to the leads table', critical: true });

if (intent === 'HOT') {
  CLAIMED.push({ node: 'Slack Router (HOT)', what: 'lead escalated to a closer (Slack + email)', critical: true });
  CLAIMED.push({ node: 'ERP Sync (HOT)',     what: 'lead written into the Bitrix24 CRM',        critical: true });
  if (origin !== 'whatsapp-bdc') {
    CLAIMED.push({ node: 'WhatsApp Outreach (HOT)', what: 'WhatsApp outreach to the customer', critical: true });
  }
} else if (intent === 'WARM') {
  if (origin !== 'whatsapp-bdc') {
    CLAIMED.push({ node: 'WhatsApp BDC (WARM)', what: 'WhatsApp outreach to the customer', critical: true });
  }
} else if (intent === 'COLD') {
  // Started, not finished: the drip spans seven days and this node is called
  // with waitForSubWorkflow = false, so the only honest claim is that it began.
  CLAIMED.push({ node: 'Marketing Drip (COLD)', what: 'lead handed to the 7-day drip (start only)', critical: true });
} else {
  CLAIMED.push({ node: 'Slack: Unclassified Lead', what: 'unclassified lead posted to Slack for a human', critical: true });
}

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  // A sub-workflow can finish green and still have failed to deliver. Lead
  // Escalation now answers with its own verdict; believe it over the exit code.
  if (typeof j.status === 'string' && /fail|unverified|error/i.test(j.status)) {
    return { ...c, ok: false, why: 'sub-workflow reported ' + j.status };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const suppressed = (origin === 'whatsapp-bdc' && (intent === 'HOT' || intent === 'WARM'))
  ? ' Outreach deliberately skipped: the customer is already in a live WhatsApp thread.'
  : '';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    intent,
    origin,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: (dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified') + suppressed,
  },
} }];
